package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.network.chat.Component;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.BlockGetter;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.block.state.StateDefinition;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;
/** Adjustable 0..15 laboratory reference source for vanilla Redstone. */
public class RedstoneReferenceSourceBlock extends Block{public static final IntegerProperty POWER=IntegerProperty.create("power",0,15);public RedstoneReferenceSourceBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(POWER,0));}@Override public MapCodec<RedstoneReferenceSourceBlock> codec(){return RedstoneEngineering.REDSTONE_REFERENCE_SOURCE_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(POWER);}@Override protected boolean isSignalSource(BlockState s){return true;}@Override protected int getSignal(BlockState s,BlockGetter l,BlockPos p,Direction d){return s.getValue(POWER);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int v=s.getValue(POWER)+(pl.isShiftKeyDown()?-1:1);if(v<0)v=15;if(v>15)v=0;BlockState n=s.setValue(POWER,v);l.setBlock(p,n,Block.UPDATE_CLIENTS);l.updateNeighborsAt(p,this);pl.displayClientMessage(Component.literal("Redstone Reference Source = "+v+"/15"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
